import {createState,scenarios,contacts,setScenario,allocatePower,selectContact,tick} from './state.js';
import {createCanvases} from './canvas.js';
import {mountHudLayout} from './layout.js';
mountHudLayout(document.getElementById('cockpit'),document.getElementById('cockpitScene'));
const $=id=>document.getElementById(id),$$=q=>[...document.querySelectorAll(q)];
const state=createState(),canvases=createCanvases($('space'),$('radar'));
const defaults={theme:'cyan',scale:100,opacity:90,glass:45,exposure:75,safeArea:false,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,highContrast:false,scene:'space',cockpitVisible:true};
const profiles={cyan:['#94e9ee','148,233,238'],amber:['#ffd39a','255,211,154'],white:['#f1f7fa','241,247,250']};
let prefs={...defaults},toastTimer,scanAnnounced=false,last=performance.now(),renderAt=0,demo=null,flareCount=12,chaffCount=24,cmReady=0,lastTrigger=null;
try{const saved=JSON.parse(localStorage.getItem('aether.hud.v1')||'null');if(saved&&typeof saved==='object'){for(const k of Object.keys(defaults)){if(typeof saved[k]===typeof defaults[k])prefs[k]=saved[k];}}}catch{}
if(!profiles[prefs.theme])prefs.theme='cyan';if(!['space','black','checker'].includes(prefs.scene))prefs.scene='space';for(const [k,min,max]of [['scale',85,115],['opacity',55,100],['glass',15,95],['exposure',25,110]])prefs[k]=Math.max(min,Math.min(max,Number.isFinite(prefs[k])?prefs[k]:defaults[k]));
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function applyPreferences(save=false){const root=document.documentElement;root.style.setProperty('--hud',profiles[prefs.theme][0]);root.style.setProperty('--hud-rgb',profiles[prefs.theme][1]);for(const k of ['scale','opacity','glass','exposure']){root.style.setProperty(k==='scale'?'--hud-scale':k==='opacity'?'--hud-opacity':`--${k}`,prefs[k]/100);$(k).value=prefs[k];$(k+'Value').textContent=prefs[k]+'%';}$('theme').value=prefs.theme;$('scene').value=prefs.scene;$('cockpitVisible').checked=prefs.cockpitVisible;$('cockpit').dataset.scene=prefs.scene;$('cockpitLayer').hidden=!prefs.cockpitVisible;for(const k of ['safeArea','reducedMotion','highContrast'])$(k).checked=prefs[k];document.body.classList.toggle('safe-area',prefs.safeArea);document.body.classList.toggle('reduced-motion',prefs.reducedMotion);document.body.classList.toggle('contrast',prefs.highContrast);if(save)try{localStorage.setItem('aether.hud.v1',JSON.stringify(prefs));}catch{notify('Browser storage unavailable. Settings apply for this session.');}}
for(const k of Object.keys(defaults))$(k).addEventListener(['theme','scene','cockpitVisible','safeArea','reducedMotion','highContrast'].includes(k)?'change':'input',()=>{prefs[k]=typeof defaults[k]==='boolean'?$(k).checked:typeof defaults[k]==='number'?Number($(k).value):$(k).value;applyPreferences(true);});
$('resetAppearance').addEventListener('click',()=>{prefs={...defaults};applyPreferences(true);notify('HUD appearance restored.');});
$('exportPreset').addEventListener('click',()=>{const data={schema:1,name:'Aether HUD',appearance:prefs,power:state.power,mode:state.mode};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='aether-hud-preset.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('HUD preset exported.');});
function toggleInspector(){if($('inspector').open){$('inspector').close();return;}lastTrigger=document.activeElement;$('inspector').show();$('inspectorToggle').setAttribute('aria-expanded','true');$('closeInspector').focus();}
$('inspectorToggle').addEventListener('click',toggleInspector);$('closeInspector').addEventListener('click',()=>$('inspector').close());$('inspector').addEventListener('close',()=>{$('inspectorToggle').setAttribute('aria-expanded','false');lastTrigger?.focus();});
$('help').addEventListener('click',()=>$('helpDialog').showModal());$('closeHelp').addEventListener('click',()=>$('helpDialog').close());
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else notify('Fullscreen is unavailable in this browser.');}catch{notify('Fullscreen is unavailable in this preview.');}});
function tab(side,name){const choices=side==='left'?['systems','power']:['contacts','target'];for(const id of choices)$(id+'Panel').hidden=id!==name;$$(`[data-${side}]`).forEach(b=>{const active=b.dataset[side]===name;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
$$('[data-left]').forEach(b=>b.addEventListener('click',()=>tab('left',b.dataset.left)));$$('[data-right]').forEach(b=>b.addEventListener('click',()=>tab('right',b.dataset.right)));$('openPower').addEventListener('click',()=>{tab('left','power');$('powerInput0').focus();});
['ENGINES','SHIELDS','SYSTEMS'].forEach((name,i)=>{const label=document.createElement('label');label.className='power-slider';label.htmlFor='powerInput'+i;label.innerHTML=`${name}<output id="powerOutput${i}"></output><input id="powerInput${i}" aria-label="${name.toLowerCase()} power allocation" type="range" min="0" max="100" value="${state.power[i]}">`;$('powerSliders').append(label);$('powerInput'+i).addEventListener('input',e=>{allocatePower(state,i,e.target.value);updatePower();});});
function updatePower(){state.power.forEach((v,i)=>{$('power'+i).textContent=v+'%';$('powerOutput'+i).textContent=v+'%';$('powerInput'+i).value=v;});}
$('balancePower').addEventListener('click',()=>{state.power=[34,33,33];updatePower();notify('Power distribution equalised.');});
function setMode(mode){state.mode=mode;$$('[data-mode]').forEach(b=>{const active=b.dataset.mode===mode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('coupled').textContent=mode==='NAV'?'COUPLED / NAVIGATION':'COUPLED / SPEED LIMITED';}
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{setMode(b.dataset.mode);notify(state.mode==='NAV'?'Navigation mode.':'Space combat manoeuvring · 200 m/s speed limit.');}));
function chooseContact(id,announce=true){if(!selectContact(state,id))return;scanAnnounced=false;tab('right','target');updateTarget();if(announce)notify('Contact selected · '+contacts.find(c=>c.id===id).name);}
for(const c of contacts){const item=document.createElement('button');item.className='contact';item.id='contact-'+c.id;item.setAttribute('aria-label',`Select ${c.name}, ${c.distance} kilometres`);item.innerHTML=`<span>${c.symbol}</span><span><strong>${c.name}</strong><small>${c.type}</small></span><b>${c.distance} KM</b>`;item.addEventListener('click',()=>chooseContact(c.id));$('contactList').append(item);const marker=document.createElement('button');marker.className='world-marker';marker.id='marker-'+c.id;marker.style.left=c.x*100+'%';marker.style.top=c.y*100+'%';marker.setAttribute('aria-label',`Select ${c.name} marker`);marker.innerHTML=`<span class="marker-shape">${c.symbol}</span><span class="marker-label">${c.name}</span><small>${c.distance} KM</small>`;marker.addEventListener('click',()=>chooseContact(c.id));$('worldMarkers').append(marker);}
function lock(){if(!state.selected){chooseContact(contacts[0].id,false);}state.locked=!state.locked;updateTarget();notify(state.locked?'Target lock acquired · '+contacts.find(c=>c.id===state.selected).name:'Target lock released.');}
function scan(){if(!state.selected)return;if(state.scanning)return;state.scan=0;state.scanning=true;scanAnnounced=false;notify(state.paused?'Scan queued · resume simulation to continue.':'Active scan initiated.');}
$('lockTarget').addEventListener('click',lock);$('scanTarget').addEventListener('click',scan);
function writeText(id,value){const el=$(id);const text=String(value);if(el.textContent!==text)el.textContent=text;}
function writeHTML(id,value){const el=$(id);if(el.innerHTML!==value)el.innerHTML=value;}
function updateTarget(){const c=contacts.find(c=>c.id===state.selected);writeText('targetCode',c?c.code:'NO TARGET');writeText('targetName',c?c.name:'SELECT A CONTACT');writeText('targetType',c?`${c.type} · ${c.distance} km`:'Choose a marker or a contact from the sensor list.');$('lockTarget').disabled=!c;$('scanTarget').disabled=!c||state.scanning;writeHTML('lockTarget',(state.locked?'Release lock':'Acquire lock')+' <kbd>T</kbd>');writeHTML('scanTarget',(state.scanning?'Scanning…':state.scan===100?'Scan again':'Scan target')+' <kbd>R</kbd>');$('scanProgress').style.width=state.scan+'%';writeText('scanResult',state.scanning?`ACTIVE SCAN / ${Math.floor(state.scan)}%`:state.scan===100?(c?.id==='unknown'?'SCAN COMPLETE · CIVILIAN TRANSPONDER / NO HOSTILE EMISSIONS':'SCAN COMPLETE · IDENTIFICATION VERIFIED'):(c?'TARGET SELECTED / '+(state.locked?'LOCK ACQUIRED':'AWAITING LOCK'):'AWAITING TARGET'));for(const c of contacts){$('contact-'+c.id).setAttribute('aria-pressed',String(state.selected===c.id));const m=$('marker-'+c.id);m.classList.toggle('selected',state.selected===c.id);m.classList.toggle('locked',state.selected===c.id&&state.locked);m.setAttribute('aria-pressed',String(state.selected===c.id));}}
$('throttle').addEventListener('input',e=>{state.throttle=Number(e.target.value);updateThrottle();});function updateThrottle(){$('throttle').value=state.throttle;$('throttleOutput').textContent=state.throttle+'%';$('throttleReadout').textContent=state.throttle+'%';}
function scenario(id,announce=true){if(!setScenario(state,id))return;$('scenario').value=id;$('missionTitle').textContent=scenarios[id].name.toUpperCase();$('missionSub').textContent={cruise:'Kepler relay · holding vector',approach:'Nacre outpost · descent corridor',encounter:'Passive tracking · identity unknown',emergency:'Divert to Nacre · systems degraded'}[id];scanAnnounced=false;tab('right','contacts');updateTarget();drawScales();if(announce)notify('Scenario · '+scenarios[id].name);render();}
$('scenario').addEventListener('change',e=>{stopDemo();scenario(e.target.value);});
function pause(){state.paused=!state.paused;$('pause').setAttribute('aria-pressed',String(state.paused));$('pause').innerHTML=state.paused?'▷ <span>Resume</span>':'Ⅱ <span>Pause</span>';notify(state.paused?'Simulation paused. Controls remain available.':'Simulation resumed.');}
$('pause').addEventListener('click',pause);$('hudToggle').addEventListener('click',()=>{const visible=!document.body.classList.contains('hud-off');document.body.classList.toggle('hud-off',visible);$('hudToggle').setAttribute('aria-pressed',String(!visible));$('hudToggle').innerHTML=`HUD ${visible?'OFF':'ON'} <kbd>H</kbd>`;});
$('ackWarning').addEventListener('click',()=>{state.acknowledged=true;render();notify('Warning acknowledged. Degraded systems remain indicated.');});
for(const name of ['flare','chaff'])$(name).addEventListener('click',()=>{if(performance.now()<cmReady){notify('Countermeasure launcher cycling.');return;}const count=name==='flare'?flareCount:chaffCount;if(count<=0){notify('No '+name+' remaining.');return;}if(name==='flare')flareCount--;else chaffCount--;cmReady=performance.now()+1200;$('flareCount').textContent=flareCount;$('chaffCount').textContent=chaffCount;$('counterStatus').textContent=name.toUpperCase()+' DEPLOYED';notify(name.toUpperCase()+' deployed · simulated defensive action.');setTimeout(()=>{$('counterStatus').textContent='DEFENSIVE SYSTEMS READY';},1600);});
function reset(){stopDemo();const wasPaused=state.paused;Object.assign(state,createState());if(wasPaused){state.paused=true;pause();}setMode('NAV');flareCount=12;chaffCount=24;cmReady=0;$('flareCount').textContent=12;$('chaffCount').textContent=24;document.body.classList.remove('hud-off');$('hudToggle').setAttribute('aria-pressed','true');$('hudToggle').innerHTML='HUD ON <kbd>H</kbd>';updatePower();updateThrottle();scenario('cruise',false);tab('left','systems');notify('Demo reset · orbital cruise.');}
$('reset').addEventListener('click',reset);
const tour=[
 {at:0,label:'01 / CRUISE · live flight instruments',action:()=>scenario('cruise',false)},
 {at:5,label:'02 / CONTACT · passive sensors detect a vessel',action:()=>scenario('encounter',false)},
 {at:9,label:'03 / TARGET · acquire a stable sensor lock',action:()=>{chooseContact('unknown',false);state.locked=true;updateTarget();}},
 {at:13,label:'04 / IDENTIFY · active scan in progress',action:scan},
 {at:19,label:'05 / EMERGENCY · prioritised systems warning',action:()=>scenario('emergency',false)},
 {at:24,label:'06 / RECOVER · redistribute power to shields',action:()=>{tab('left','power');allocatePower(state,1,65);updatePower();}},
 {at:29,label:'07 / APPROACH · select a safe landing site',action:()=>{scenario('approach',false);chooseContact('port',false);state.locked=true;updateTarget();}},
 {at:35,label:'Tour complete',action:()=>{stopDemo();notify('Demo complete. Explore the controls or open the HUD inspector.');}}
];
function stopDemo(){demo=null;$('runDemo').textContent='▷ Run demo';$('demoProgress').hidden=true;}
$('runDemo').addEventListener('click',()=>{if(demo){stopDemo();notify('Guided demo stopped.');return;}if(state.paused)pause();state.throttle=62;updateThrottle();state.power=[34,33,33];updatePower();tab('left','systems');demo={elapsed:0,step:-1};$('runDemo').textContent='■ Stop demo';$('demoProgress').hidden=false;});
function drawScales(){const center=state.heading;let compass='';for(let i=-12;i<=12;i++){const x=270+i*20,n=(center+i*5+360)%360;compass+=`<path d="M${x} 25v${i%2===0?9:4}" opacity="${i%2===0?.65:.35}"/>`;if(i%4===0)compass+=`<text x="${x}" y="18">${String(n).padStart(3,'0')}</text>`;}compass+='<path d="M260 46h20l-10-7Z" fill="currentColor"/><path d="M270 23v12"/>';$('compass').innerHTML=compass;$('heading').textContent=String(center).padStart(3,'0');
 let ladder='';for(let i=-2;i<=2;i++){if(i===0)continue;const y=237+i*48;ladder+=`<path d="M302 ${y}h32m52 0h32" opacity=".36"/><text class="tape-label" x="287" y="${y+4}" font-size="9">${Math.abs(i*5)}</text>`;}$('pitchLadder').innerHTML=ladder;$('pitchLadder').setAttribute('transform',`translate(0,${state.pitch*2})`);}
let previousTapeKey='';
function tapes(){const key=Math.round(state.speed/50)+':'+state.altitude;if(key===previousTapeKey)return;previousTapeKey=key;let a='',b='';for(let i=-3;i<=3;i++){const y=237+i*42;const vel=Math.max(0,Math.round(state.speed/50)*50-i*50);const alt=state.altitude>=10000?Math.max(0,state.altitude/1000-i*.5).toFixed(1):String(Math.max(0,state.altitude-i*500));a+=`<path d="M205 ${y}h${i%2?9:15}" opacity=".5"/><text x="183" y="${y+4}" text-anchor="end" class="tape-label" opacity=".45">${vel}</text>`;b+=`<path d="M515 ${y}h${i%2?-9:-15}" opacity=".5"/><text x="539" y="${y+4}" class="tape-label" opacity=".45">${alt}</text>`;}a+='<path d="M205 98v278" opacity=".4"/>';b+='<path d="M515 98v278" opacity=".4"/>';$('speedTape').innerHTML=a;$('altTape').innerHTML=b;}
function render(){
 writeText('speed',Math.round(state.speed));writeText('altitude',state.altitude>=10000?(state.altitude/1000).toFixed(1):Math.round(state.altitude).toLocaleString('en-US'));writeText('altitudeUnit',state.altitude>=10000?'ALT / KM':'ALT / M');writeText('heatReadout',Math.round(state.heat)+'°C');writeText('shieldNumber',Math.round(state.shield));
 for(const k of ['shield','hull','fuel']){writeText(k+'Value',Math.round(state[k])+'%');$(k+'Bar').style.width=state[k]+'%';$(k+'Bar').style.backgroundColor=k==='shield'&&state.shield<35?'var(--warning)':'';}
 writeText('systemStatus',state.warning?(state.scenario==='emergency'?'! SYSTEMS DEGRADED':'! CONTACT CAUTION'):'ALL SYSTEMS NOMINAL');$('systemStatus').style.color=state.warning?'var(--warning)':'';$('shieldNumber').style.color=state.shield<35?'var(--warning)':'';$('ship').style.color=state.shield<35?'var(--warning)':'';$('warning').hidden=!state.warning||state.acknowledged;writeText('warningText','⚠ '+state.warning);writeText('sensorStatus',state.locked?'TARGET LOCK ACTIVE':'SENSOR FUSION ACTIVE');
 updateTarget();tapes();if(state.scan===100&&!scanAnnounced){scanAnnounced=true;notify('Scan complete · '+(state.selected==='unknown'?'civilian transponder detected.':'identification verified.'));}
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('inspector').open&&$('inspector').close();return;}if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||$('helpDialog').open||e.target.closest('input,select,textarea,button,summary,[contenteditable]'))return;const key=e.key.toLowerCase();if(e.code==='Space'){e.preventDefault();pause();}else if(key==='i')toggleInspector();else if(key==='h')$('hudToggle').click();else if(key==='t')lock();else if(key==='r')scan();});
function frame(now){const dt=Math.min((now-last)/1000,.1);last=now;if(!document.hidden){tick(state,dt);if(demo&&!state.paused){demo.elapsed+=dt;const n=tour.findLastIndex(step=>step.at<=demo.elapsed);if(n!==demo.step){demo.step=n;$('demoStep').textContent=tour[n].label;tour[n].action();}if(demo)$('demoTimer').style.width=demo.elapsed/35*100+'%';}if(now-renderAt>50){renderAt=now;render();canvases.draw(state.time,state,profiles[prefs.theme][0],prefs.reducedMotion,prefs.scene==='space');}}requestAnimationFrame(frame);}
applyPreferences();updatePower();updateThrottle();drawScales();render();requestAnimationFrame(frame);
